def pagehero(kicker,title,desc):return f'<section class="page-hero"><div class="container"><span class="kicker">{kicker}</span><h1>{title}</h1><p>{desc}</p></div></section>'
def card(img,tag,title,desc,href='#',extra=''):
 return f'<article class="card" data-category="{extra or "all"}"><div class="card-image"><img src="{img}" alt="{title}" loading="lazy"></div><div class="card-body"><span class="tag">{tag}</span><h3>{title}</h3><p>{desc}</p><a class="text-link" href="{href}">بیشتر بدانید ←</a></div></article>'
